96	// 否则会出现「回调等锁 <-> wait() 等 SUBACK」死锁。故：
97	// - handler_mutex_ 只在拷贝/清空 handler_ 的瞬间持有（微秒级）；
98	// - client_ 只被执行器线程访问（Connect/Publish/Disconnect 均在执行器线程），无需加锁；
99	// - Disconnect 先清空 handler（回调变 no-op），再用 in_flight 计数器 + 条件变量
100	//   等待在途回调退出，最后销毁 client（防止析构期回调触碰已释放的节点成员）；
101	// - C1 重连补订阅：connected 回调跑在 Paho 回调线程，只做一次原子置位
102	//   need_resubscribe_（绝不 subscribe/wait——那会与 SUBACK 处理互锁），
103	//   补订阅由执行器线程的 5s 定时器经 ConsumeResubscribeRequest()+Resubscribe() 完成。
104	// ============================================================
105	class MqttClientWrapper {
106	 public:
107	  using MessageHandler = std::function<void(const std::string& topic, const std::string& payload)>;
108	
109	  ~MqttClientWrapper() { Disconnect(); }
110	
111	  MqttClientWrapper() = default;
112	  MqttClientWrapper(const MqttClientWrapper&) = delete;
113	  MqttClientWrapper& operator=(const MqttClientWrapper&) = delete;
114	
115	  /// 建立连接并订阅主题（订阅过滤器按 (topic, qos) 成对传入，支持 per-topic QoS）。
116	  /// 成功后启用 automatic_reconnect 自动重连；失败返回 false 并销毁半成品客户端
117	  /// （由调用方定时重试重建）。clean_session=true，故每次(重)连接都必须补订阅——
118	  /// 首连由本方法同步完成，后续重连由 connected 回调置位 + Resubscribe() 补齐。
119	  bool Connect(const std::string& broker_uri, const std::string& client_id,
120	               const std::vector<std::pair<std::string, int>>& sub_filters,
121	               const std::string& lwt_topic, const std::string& lwt_payload, int lwt_qos,
122	               MessageHandler handler, std::string* error) {
123	    {
124	      std::lock_guard<std::mutex> lock(handler_mutex_);
125	      handler_ = std::move(handler);
126	    }
127	    QuiesceCallbacks();  // 等待旧 client 的在途回调退出后再销毁
128	    DestroyClient();
129	    try {
130	      sub_filters_ = sub_filters;  // 执行器线程独占；Resubscribe 在同线程读取
131	      need_resubscribe_.store(false, std::memory_order_release);
132	      client_ = std::make_unique<mqtt::async_client>(broker_uri, client_id);
133	      client_->set_message_callback([this](mqtt::const_message_ptr msg) {
134	        in_flight_.fetch_add(1, std::memory_order_acq_rel);
135	        MessageHandler handler;
136	        {
137	          std::lock_guard<std::mutex> lock(handler_mutex_);
138	          handler = handler_;
139	        }
140	        if (handler && msg) {
141	          handler(msg->get_topic(), msg->to_string());
142	        }
143	        if (in_flight_.fetch_sub(1, std::memory_order_acq_rel) == 1) {
144	          std::lock_guard<std::mutex> lock(done_mutex_);
145	          done_cv_.notify_all();
146	        }
147	      });
148	      // C1：clean session 下 broker 不保留订阅，automatic_reconnect 重连成功后
149	      // 订阅已丢失且无任何错误信号。connected 回调（含首连与每次重连）只置位标志，
150	      // 补订阅由执行器线程完成——回调线程内对 SUBACK token wait() 会死锁。
151	      client_->set_connected_handler([this](const std::string& /*cause*/) {
152	        need_resubscribe_.store(true, std::memory_order_release);
153	      });
154	      mqtt::connect_options_builder builder;
155	      builder.clean_session(true)
156	          .automatic_reconnect(std::chrono::seconds(1), std::chrono::seconds(60))
157	          .connect_timeout(std::chrono::seconds(5))
158	          .keep_alive_interval(std::chrono::seconds(15))
159	          .will(mqtt::will_options(lwt_topic, lwt_payload, lwt_qos, true /*retained*/));
160	      if (!client_->connect(builder.finalize())->wait_for(std::chrono::seconds(10))) {
161	        if (error != nullptr) *error = "连接超时";
162	        DestroyClient();
163	        return false;
164	      }
165	      for (const auto& [filter, qos] : sub_filters_) {
166	        if (!client_->subscribe(filter, qos)->wait_for(std::chrono::seconds(5))) {
167	          if (error != nullptr) *error = "订阅超时: " + filter;
168	          DestroyClient();
169	          return false;
170	        }
171	      }
172	      connected_once_.store(true);
173	      // 首连订阅刚完成，清掉连接回调在 CONNACK 窗口置的位，避免紧接着一次冗余补订阅；
174	      // 此后任何(重)连接事件都会重新置位（窗口为循环结束到此行的纳秒级，丢失即由下
175	      // 一次连接回调覆盖）
176	      need_resubscribe_.store(false, std::memory_order_release);
177	      return true;
178	    } catch (const std::exception& e) {
179	      if (error != nullptr) *error = e.what();
180	      DestroyClient();
181	      return false;
182	    }
183	  }
184	
185	  /// 执行器线程：取走并清零「需要补订阅」请求（回调线程只置位，不做阻塞调用）。
186	  bool ConsumeResubscribeRequest() {
187	    return need_resubscribe_.exchange(false, std::memory_order_acq_rel);
188	  }
189	
190	  /// 重连后补订阅（仅执行器线程调用）。失败自动重新置位标志，下个定时器周期重试。
191	  bool Resubscribe(std::string* error) {
192	    if (client_ == nullptr) {
193	      need_resubscribe_.store(true, std::memory_order_release);
194	      if (error != nullptr) *error = "MQTT 客户端未初始化";
195	      return false;
196	    }
197	    if (!client_->is_connected()) {
198	      // 尚未重连完成：保留请求，由下个周期重试（重连成功时 connected 回调也会置位）
199	      need_resubscribe_.store(true, std::memory_order_release);
200	      if (error != nullptr) *error = "MQTT 未连接";
201	      return false;
202	    }
203	    try {
204	      for (const auto& [filter, qos] : sub_filters_) {
205	        if (!client_->subscribe(filter, qos)->wait_for(std::chrono::seconds(5))) {
206	          need_resubscribe_.store(true, std::memory_order_release);
207	          if (error != nullptr) *error = "补订阅超时: " + filter;
208	          return false;
209	        }
210	      }
211	      return true;
212	    } catch (const std::exception& e) {
213	      need_resubscribe_.store(true, std::memory_order_release);
214	      if (error != nullptr) *error = e.what();
215	      return false;
216	    }
217	  }
218	
219	  /// 发布消息。未连接时快速失败（返回 false），绝不阻塞执行器线程。
220	  /// 仅允许在执行器线程调用（与 Connect/Disconnect 串行）。
221	  /// wait > 0 时同步等待 broker 确认（QoS1 需要，供关机路径确保送达后才断连）。
222	  bool Publish(const std::string& topic, const std::string& payload, int qos, bool retained,
223	               std::string* error,
224	               std::chrono::milliseconds wait = std::chrono::milliseconds(0)) {
225	    if (client_ == nullptr) {
226	      if (error != nullptr) *error = "MQTT 客户端未初始化";
227	      return false;
228	    }
229	    if (!client_->is_connected()) {
230	      if (error != nullptr) *error = "MQTT 未连接";
231	      return false;
232	    }
233	    try {
234	      auto token = client_->publish(mqtt::make_message(topic, payload.data(), payload.size(), qos,
235	                                                       retained));
236	      if (wait.count() > 0 && !token->wait_for(wait)) {
237	        if (error != nullptr) *error = "发布确认超时";
238	        return false;
239	      }
240	      return true;
241	    } catch (const std::exception& e) {
242	      if (error != nullptr) *error = e.what();
243	      return false;
244	    }
245	  }
