247	  bool HasConnectedOnce() const { return connected_once_.load(); }
248	
249	  /// 优雅断连：不触发 LWT 遗嘱（正常下线不应广播 CONNECTIONBROKEN）。
250	  void Disconnect() {
251	    {
252	      std::lock_guard<std::mutex> lock(handler_mutex_);
253	      handler_ = nullptr;  // 回调屏障：此后的回调拷贝到空 handler 直接 no-op
254	    }
