379	    std::string err;
380	    mqtt_->Publish(MqttTopic(manufacturer_, serial_number_, "connection"),
381	                   BuildGatewayConnectionJson("CONNECTIONBROKEN"), kQosConnection,
382	                   true /*retained*/, &err, std::chrono::seconds(2));
