388	void Vda5050GatewayNode::TryConnectMqtt() {
389	  if (!mqtt_) return;
390	  if (mqtt_->HasConnectedOnce()) {
391	    // C1：首连成功后连接由 automatic_reconnect 接管，本定时器只剩一件事——
392	    // 重连补订阅。clean_session=true 下 broker 不保留订阅，且订阅丢失无任何
393	    // 错误信号；连接回调线程只置标志（在回调里 wait() SUBACK 会与 Paho
394	    // receiveThread 死锁），补订阅统一在执行器线程完成。
395	    if (mqtt_->ConsumeResubscribeRequest()) {
396	      std::string err;
397	      if (mqtt_->Resubscribe(&err)) {
398	        RCLCPP_INFO(get_logger(), "MQTT (重)连接后已补订阅 %s/+/+/{state,connection}",
399	                    TopicBase().c_str());
400	      } else if (err != "MQTT 未连接") {
401	        // "MQTT 未连接"属正常窗口（断线中，重连回调会再次置位），不告警
402	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
403	                             "重连后补订阅失败: %s（5s 后重试）", err.c_str());
404	      }
405	    }
406	    return;
407	  }
408	  const std::string uri = "tcp://" + mqtt_broker_host_ + ":" + std::to_string(mqtt_port_);
409	  const std::string client_id = "amr_dispatcher_gateway_" + serial_number_;
410	  // M3：按 topic 配对传 QoS（state 用 0 与发布侧对齐，connection 用 1 保证心跳到达）
411	  const std::vector<std::pair<std::string, int>> filters = {
412	      {TopicBase() + "/+/+/state", kQosState}, {TopicBase() + "/+/+/connection", kQosConnection}};
413	  // M1（观察项）：LWT payload 冻结在连接时刻的 headerId/timestamp——MQTT 3.1.1
414	  // 遗嘱在 broker 侧触发，网关无法在断线后更新它。对端若按 headerId 严格排序
415	  // 需容忍回退；payload 的 connectionState/serialNumber 不受影响。
416	  const std::string lwt_topic = MqttTopic(manufacturer_, serial_number_, "connection");
417	  const std::string lwt_payload = BuildGatewayConnectionJson("CONNECTIONBROKEN");
418	
419	  std::string err;
420	  // M7（已知取舍）：首连同步 wait 最长阻塞执行器线程 10s——v1 可接受
421	  // （仅启动期一次性成本，heartbeat/drain 在此期间暂停不影响安全）；
422	  // 失败后由本定时器每 5s 重试，首连成功即交给 automatic_reconnect。
423	  const bool ok = mqtt_->Connect(
424	      uri, client_id, filters, lwt_topic, lwt_payload, kQosConnection,
425	      [this](const std::string& topic, const std::string& payload) {
426	        OnMqttMessage(topic, payload);
427	      },
428	      &err);
429	  if (ok) {
430	    RCLCPP_INFO(get_logger(), "MQTT 已连接 %s (client_id=%s, base=%s, LWT=%s)", uri.c_str(),
431	                client_id.c_str(), TopicBase().c_str(), lwt_topic.c_str());
432	  } else {
433	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
434	                         "MQTT 连接失败 %s: %s（首连前每 5s 重试，首连成功后由自动重连接管）",
435	                         uri.c_str(), err.c_str());
436	  }
437	}
