439	void Vda5050GatewayNode::OnMqttMessage(const std::string& topic, std::string payload) {
440	  std::lock_guard<std::mutex> lock(inbound_mutex_);
441	  if (inbound_queue_.size() >= kMaxInboundQueue) {
442	    inbound_queue_.pop_front();
443	    dropped_messages_.fetch_add(1, std::memory_order_relaxed);
444	  }
445	  inbound_queue_.emplace_back(topic, std::move(payload));
446	}
