448	void Vda5050GatewayNode::DrainInboundQueue() {
449	  std::deque<std::pair<std::string, std::string>> batch;
450	  {
451	    std::lock_guard<std::mutex> lock(inbound_mutex_);
452	    batch.swap(inbound_queue_);
453	  }
454	  const std::size_t dropped = dropped_messages_.exchange(0, std::memory_order_relaxed);
455	  if (dropped > 0) {
456	    RCLCPP_WARN(get_logger(),
457	                "入站队列溢出，丢弃 %zu 条 MQTT 消息（可调低负载或提高出队频率 kDrainPeriodMs）",
458	                dropped);
459	  }
460	  for (const auto& item : batch) {
461	    const InboundTopic parsed = ParseInboundTopic(item.first);
462	    if (!parsed.valid) {
463	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "忽略无法解析的 MQTT Topic: %s",
464	                           item.first.c_str());
465	      continue;
466	    }
467	    // M2：按 (manufacturer, serialNumber) 配对过滤网关自身心跳/LWT——只比 serial
468	    // 会把同 serial 不同厂商的真车误杀，不比则其他网关的心跳会被当车辆上线
469	    if (parsed.manufacturer == manufacturer_ && parsed.vehicle_id == serial_number_) {
470	      continue;
