624	Vda5050GatewayNode::VehicleEndpoints& Vda5050GatewayNode::EnsureVehicle(
625	    const std::string& vehicle_id, const std::string& manufacturer) {
626	  auto it = vehicles_.find(vehicle_id);
627	  if (it != vehicles_.end()) {
628	    return it->second;
629	  }
630	  VehicleEndpoints ep;
631	  ep.manufacturer = manufacturer;  // manufacturer 以首见为准，保证后续原路回发
632	  if (!IsValidVehicleId(vehicle_id)) {
633	    RCLCPP_ERROR(get_logger(),
634	                 "serialNumber '%s' 不是合法 ROS 话题段（须字母或 '_' 开头，仅含字母/数字/'_'），"
635	                 "跳过该车全部 ROS 端点创建（MQTT 订阅解析不受影响）",
636	                 vehicle_id.c_str());
637	  } else {
638	    try {
639	      const std::string base = "/fleet/" + vehicle_id;
640	      ep.state_pub = create_publisher<std_msgs::msg::String>(base + "/state", 10);
641	      ep.pose_pub = create_publisher<geometry_msgs::msg::PoseStamped>(base + "/pose", 10);
642	      ep.online_pub = create_publisher<std_msgs::msg::Bool>(
643	          base + "/online", rclcpp::QoS(rclcpp::KeepLast(1)).transient_local());
644	      ep.send_order_sub = create_subscription<std_msgs::msg::String>(
645	          base + "/send_order", 10,
646	          [this, vehicle_id, manufacturer](const std_msgs::msg::String::SharedPtr m) {
647	            SendOrderCallback(vehicle_id, manufacturer, m);
648	          });
649	      ep.instant_actions_sub = create_subscription<std_msgs::msg::String>(
650	          base + "/instant_actions", 10,
651	          [this, vehicle_id, manufacturer](const std_msgs::msg::String::SharedPtr m) {
652	            InstantActionsCallback(vehicle_id, manufacturer, m);
653	          });
654	      RCLCPP_INFO(get_logger(),
655	                  "发现车辆 %s (manufacturer=%s)，已创建 ROS 端点 %s/{state,pose,online,send_order,instant_actions}",
656	                  vehicle_id.c_str(), manufacturer.c_str(), base.c_str());
657	    } catch (const std::exception& e) {
658	      RCLCPP_ERROR(get_logger(), "创建车辆 %s 的 ROS 端点失败: %s", vehicle_id.c_str(), e.what());
659	      ep = VehicleEndpoints{};  // 部分创建失败则整体放弃，避免半残端点
660	      ep.manufacturer = manufacturer;
661	      // M6（观察项，v1 不修）：失败端点会被永久缓存（此后该车不再重试创建，
662	      // 消息被无 pub 的空端点静默丢弃），需重启网关恢复。触发条件是 topic 名
663	      // 非法/资源耗尽等，IsValidVehicleId 已前置拦掉最常见的一类。
664	    }
665	  }
666	  return vehicles_.emplace(vehicle_id, std::move(ep)).first->second;
667	}
