669	Vda5050GatewayNode::InboundTopic Vda5050GatewayNode::ParseInboundTopic(const std::string& topic) {
670	  InboundTopic out;
671	  std::vector<std::string> parts;
672	  std::size_t start = 0;
673	  while (start <= topic.size()) {
674	    const std::size_t pos = topic.find('/', start);
675	    if (pos == std::string::npos) {
676	      parts.push_back(topic.substr(start));
677	      break;
678	    }
679	    parts.push_back(topic.substr(start, pos - start));
680	    start = pos + 1;
681	  }
682	  if (parts.size() != 5) {
683	    return out;  // base/manufacturer/serial/leaf 才是 4 段；此处 topic 含首段，共 5
684	  }
685	  if (parts[4] != "state" && parts[4] != "connection") {
686	    return out;
687	  }
688	  if (parts[2].empty() || parts[3].empty()) {
689	    return out;
690	  }
691	  out.valid = true;
692	  out.manufacturer = parts[2];
693	  out.vehicle_id = parts[3];
694	  out.leaf = parts[4];
695	  return out;
696	}
