698	bool Vda5050GatewayNode::IsValidVehicleId(const std::string& vehicle_id) {
699	  if (vehicle_id.empty()) return false;
700	  const auto ok_first = [](char c) {
701	    return std::isalpha(static_cast<unsigned char>(c)) != 0 || c == '_';
702	  };
703	  if (!ok_first(vehicle_id[0])) return false;
704	  for (const char c : vehicle_id) {
705	    if (std::isalnum(static_cast<unsigned char>(c)) == 0 && c != '_') return false;
706	  }
707	  return true;
708	}
